import cn.acg138.robotphone.SonarPresentation;
import org.json.JSONObject;
import org.json.JSONArray;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Actual native sonar_diagnostics_json output plus bounded malformed-input tests. */
public final class SonarPresentationTests {
    static int checks;static final Map<String,String> actual=new HashMap<>();
    static void check(boolean value,String reason){if(!value)throw new AssertionError(reason);checks++;}
    static JSONObject state(String name){return new JSONObject(actual.get(name));}
    static JSONObject health(JSONObject state){return state.optJSONObject("navigation").optJSONObject("sonar_health");}
    static JSONObject front(JSONObject state){return health(state).optJSONArray("channels").optJSONObject(0);}
    static String line(JSONObject value){return SonarPresentation.line(value,true,10000,10000);}
    public static void main(String[] args)throws Exception {
        for(String row:Files.readAllLines(Paths.get(args[0]),StandardCharsets.UTF_8)) {
            JSONObject fixture=new JSONObject(row);actual.put(fixture.optString("case"),fixture.optJSONObject("state").toString());
        }
        check(actual.size()==10,"fixtures generated by real RK sonar diagnostics producer");
        check(line(state("normal")).equals("L:0.82m  F:1.23m  R:>4m"),"native F/L/R order is presented as L/F/R in metres");
        check(line(state("four_metres")).equals("L:0.82m  F:4.00m  R:>4m"),"4000mm stays4.00m; only greater than4000 becomes >4m");
        check(line(state("fpga_invalid")).equals("L:0.82m  F:无效  R:>4m"),"invalid front never shows retained last_accepted_mm");
        check(line(state("packet_expired")).equals("L:过期  F:过期  R:过期"),"native packet expiry is shown without old normal ranges");
        check(line(state("source_expired")).equals("L:0.82m  F:过期  R:>4m"),"native source expiry is per channel");
        check(line(state("not_received")).equals("L:—  F:—  R:—"),"no packet is not invented far/free range");
        check(line(state("not_observed")).contains("F:—"),"native unobserved front has no range");
        check(line(state("saturated_source")).contains("F:过期"),"saturated source age never reuses retained normal range");
        check(line(state("outside_range")).contains("F:无效"),"native outside-config range remains invalid");
        check(line(state("host_time_invalid")).equals("L:无效  F:无效  R:无效"),"native clock fault cannot present healthy ranges");
        check(SonarPresentation.line(state("normal"),false,10000,10000).equals("L:—  F:—  R:—"),"disconnect clears last valid ranges");
        check(SonarPresentation.line(state("normal"),true,10000,11001).equals("L:过期  F:过期  R:过期"),"stale phone state cannot retain valid numbers");
        check(SonarPresentation.line(state("normal"),true,10000,10241).equals("L:过期  F:过期  R:过期"),"packet ages continue advancing while no phone state arrives");
        check(SonarPresentation.line(state("normal"),true,10000,10239).contains("F:1.23m"),"fresh packet remains readable inside actual native timeout");
        check(SonarPresentation.line(state("normal"),true,10000,9999).contains("F:过期"),"backwards phone clock cannot preserve a range");
        JSONObject s=state("normal");s.put("gateway_state_age_ms",250);check(line(s).contains("F:1.23m"),"dashboard cache age is not double-added to live navigation sonar health");
        s=state("normal");s.put("gateway_control_pending",true);check(line(s).contains("F:1.23m"),"pending dashboard control does not change separately fresh navigation sonar health");
        s=state("normal");front(s).put("fault",true);check(line(s).contains("F:无效"),"fault bit overrides a contradictory status string");
        s=state("normal");front(s).put("navigation_usable",false);check(line(s).contains("F:无效"),"navigation-unusable channel is never shown as normal range");
        s=state("normal");front(s).put("valid",false);check(line(s).contains("F:无效"),"reported valid bit is required independently");
        s=state("normal");front(s).put("last_accepted_mm",Double.NaN);check(line(s).contains("F:—"),"nonfinite range is rejected");
        s=state("normal");front(s).put("last_accepted_mm",null);check(line(s).contains("F:—"),"missing numeric range is rejected");
        s=state("normal");front(s).put("last_accepted_mm",65535);check(line(s).contains("F:—"),"FFFF cannot look like >4m");
        s=state("normal");front(s).put("last_accepted_mm",4000.5);check(line(s).contains("F:—"),"malformed fractional millimetres are rejected");
        s=state("normal");front(s).put("total_age_ms",null);check(line(s).contains("F:过期"),"unknown source age does not look fresh");
        s=state("normal");front(s).put("total_age_ms",740);check(SonarPresentation.line(s,true,10000,10011).contains("F:过期"),"source age advances using phone elapsed time");
        s=state("normal");health(s).put("navigation_packet_timeout_ms",Double.POSITIVE_INFINITY);check(line(s).contains("F:过期"),"nonfinite age policy cannot claim a fresh range");
        s=state("normal");JSONObject h=health(s);JSONArray c=h.optJSONArray("channels");h.put("channels",new JSONArray(c.optJSONObject(2),c.optJSONObject(0),c.optJSONObject(1)));check(line(s).equals("L:0.82m  F:1.23m  R:>4m"),"channel identity remains correct if producer array is reordered");
        s=state("normal");health(s).put("channels",new JSONArray());check(line(s).equals("L:—  F:—  R:—"),"missing channels are not replaced from older state");
        check(line(new JSONObject()).equals("L:—  F:—  R:—"),"older service without sonar diagnostics displays unavailable");
        check(SonarPresentation.line(null,true,0,100).equals("L:—  F:—  R:—"),"null startup state is safe");
        System.out.println("PASS "+checks+" sonar presentation checks using native RK diagnostics fixtures");
    }
}
